final class CoreOS {
    private static function text($v,int $max=255): string { $s=trim((string)$v); return function_exists('mb_substr')?mb_substr($s,0,$max,'UTF-8'):substr($s,0,$max); }
    private static function nullable($v,int $max=255): ?string { $s=self::text($v,$max); return $s===''?null:$s; }
    private static function ref(string $prefix,int $id): string { return sprintf('%s-%s-%06d',$prefix,date('Y'),$id); }
    private static function json($v): string { return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); }
    private static function body(): array { return Http::body(); }
    private static function requirePerm(PDO $db,array $user,string $perm): void { Auth::requirePermission($db,$user,$perm); }
    private static function exists(PDO $db,string $sql,array $args): bool { $st=$db->prepare($sql);$st->execute($args);return (bool)$st->fetchColumn(); }
    private static function one(PDO $db,string $sql,array $args=[]): ?array { $st=$db->prepare($sql);$st->execute($args);$r=$st->fetch();return $r?:null; }
    private static function all(PDO $db,string $sql,array $args=[]): array { $st=$db->prepare($sql);$st->execute($args);return $st->fetchAll(); }
    private static function tableExists(PDO $db,string $table): bool { $st=$db->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?");$st->execute([$table]);return (int)$st->fetchColumn()>0; }
    private static function can(PDO $db,array $user,string $perm): bool { return Auth::can($db,(int)$user['id'],$perm); }

