    private static function closeTaskByRule(PDO $db,int $companyId,string $entityType,int $entityId,string $ruleCode): void {
        $st=$db->prepare("UPDATE tasks SET status='DONE',completed_at=NOW() WHERE company_id=? AND entity_type=? AND entity_id=? AND rule_code=? AND status IN ('OPEN','SNOOZED')");
        $st->execute([$companyId,$entityType,$entityId,$ruleCode]);
    }
    private static function ensureTask(PDO $db,int $companyId,int $ownerId,string $title,string $entityType,int $entityId,?string $due,string $priority,string $rule): void {
        $st=$db->prepare("SELECT id FROM tasks WHERE company_id=? AND entity_type=? AND entity_id=? AND rule_code=? AND status IN ('OPEN','SNOOZED') LIMIT 1");
        $st->execute([$companyId,$entityType,$entityId,$rule]);
        if($st->fetchColumn()) return;
        $ins=$db->prepare("INSERT INTO tasks(company_id,title,entity_type,entity_id,owner_user_id,due_at,priority,status,source,rule_code) VALUES(?,?,?,?,?,?,?,'OPEN','AUTOMATION',?)");
        $ins->execute([$companyId,$title,$entityType,$entityId,$ownerId,$due,$priority,$rule]);
    }

    public static function quotePrice(PDO $db,int $qvId,array $patch=[]): array {
        $qv=self::one($db,'SELECT * FROM quote_versions WHERE id=?',[$qvId]);
        if(!$qv) Http::json(['ok'=>false,'error'=>'NOT_FOUND'],404);
        if(QuoteVs2Repository::engine($qv)==='VS2_1')return Vs2Snapshots::summary($db,$qv);
        $option=self::one($db,"SELECT snapshot_json FROM quote_options WHERE quote_version_id=? ORDER BY CASE hotel_level WHEN '4*' THEN 0 ELSE 1 END,hotel_level LIMIT 1",[$qvId]);
        if($option){$s=json_decode($option['snapshot_json'],true);$p=$s['pricing'];return ['total_cost'=>$p['cost_total']*$s['fx_rate'],'cost_per_paying_pax'=>$p['cost_total']/max(1,$s['paying_pax']),'selling_per_pax'=>$p['selling_per_pax'],'total_selling'=>$p['total_selling'],'profit_amount'=>$p['profit'],'margin_pct'=>$p['margin_pct'],'markup_pct'=>$p['markup_pct'],'pricing_mode'=>$p['pricing_mode'],'pricing_value'=>$p['pricing_value'],'rounding_step'=>$p['rounding_step'],'fx_rate'=>$s['fx_rate'],'items'=>[]];}
        $items=self::all($db,'SELECT * FROM quote_cost_items WHERE quote_version_id=? ORDER BY sort_order,id',[$qvId]);
        $fx=max(0.000001,(float)($patch['fx_rate']??$qv['fx_rate']));
        $pay=max(1,(int)($patch['paying_pax']??$qv['paying_pax']));
        $costVnd=0.0;
        foreach($items as $it){
            $amount=(float)$it['total']; $cur=strtoupper((string)$it['currency']);
            $costVnd += $cur==='USD' ? $amount*$fx : $amount;
        }
        $costUsd=$costVnd/$fx;
        $cpp=$costUsd/$pay;
        $mode=strtoupper((string)($patch['pricing_mode']??$qv['pricing_mode']));
        $value=(float)($patch['pricing_value']??$qv['pricing_value']);
        $step=max(0,(float)($patch['rounding_step']??$qv['rounding_step']));
        $manual=array_key_exists('selling_per_pax',$patch)?(float)$patch['selling_per_pax']:(float)$qv['selling_per_pax'];
        if($mode==='TARGET_MARGIN'){
            $den=1-($value/100); if($den<=0.00001) Http::json(['ok'=>false,'error'=>'VALIDATION','message'=>'Target margin must be below 100%.'],422);
            $sell=$cpp/$den;
        }elseif($mode==='MANUAL'){
            $sell=max(0,$manual);
        }else{
            $mode='MARKUP'; $sell=$cpp*(1+$value/100);
        }
        if($step>0 && $mode!=='MANUAL') $sell=ceil($sell/$step)*$step;
        $totalSelling=$sell*$pay;
        $profit=$totalSelling-$costUsd;
        $margin=$totalSelling>0?$profit/$totalSelling*100:0;
        $markup=$costUsd>0?$profit/$costUsd*100:0;
        return [
            'total_cost'=>$costVnd,'cost_per_paying_pax'=>$cpp,'selling_per_pax'=>$sell,
            'total_selling'=>$totalSelling,'profit_amount'=>$profit,'margin_pct'=>$margin,'markup_pct'=>$markup,
            'pricing_mode'=>$mode,'pricing_value'=>$value,'rounding_step'=>$step,'fx_rate'=>$fx,'items'=>$items
        ];
    }
    private static function saveQuotePatch(PDO $db,array $qv,array $b,int $userId): array {
        // Re-read after acquiring the write lock: a quote may have been sent since the route read it.
        $qv=self::one($db,'SELECT * FROM quote_versions WHERE id=? FOR UPDATE',[$qv['id']]);QuoteVs2Repository::legacy($qv);
        if(in_array($qv['version_status'],['SENT','CONFIRMED','SUPERSEDED'],true)) Http::json(['ok'=>false,'error'=>'IMMUTABLE_VERSION','message'=>'Sent or confirmed quote versions cannot be edited. Create a new revision.'],409);
        $schedule=$b['schedule']??(json_decode((string)($qv['schedule_json']??'[]'),true)?:[]);
        $schedule=ScheduleImport::normalize($schedule);
        $language=$b['document_language']??$qv['document_language']??'en';if(!in_array($language,['en','vi'],true))throw new InvalidArgumentException('Invalid document language');
        $proposal=$b['proposal']??(json_decode((string)($qv['proposal_json']??'{}'),true)?:[]);
        $status=$qv['version_status']==='APPROVED'?'DRAFT':$qv['version_status'];
        $fields=[
            'tour_name'=>self::text($b['tour_name']??$qv['tour_name'],255),
            'start_date'=>self::nullable($b['start_date']??$qv['start_date'],10),
            'end_date'=>self::nullable($b['end_date']??$qv['end_date'],10),
            'adults'=>(int)($b['adults']??$qv['adults']),'children'=>(int)($b['children']??$qv['children']),'infants'=>(int)($b['infants']??$qv['infants']),'foc'=>(int)($b['foc']??$qv['foc']),
            'total_guests'=>(int)($b['total_guests']??$qv['total_guests']),'paying_pax'=>(int)($b['paying_pax']??$qv['paying_pax']),
            'hotel_level'=>self::nullable($b['hotel_level']??$qv['hotel_level'],32),'tour_type'=>self::nullable($b['tour_type']??$qv['tour_type'],64),'guide_language'=>self::nullable($b['guide_language']??$qv['guide_language'],80),'meals'=>self::nullable($b['meals']??$qv['meals'],255),
            'fx_rate'=>(float)($b['fx_rate']??$qv['fx_rate']),'pricing_mode'=>strtoupper(self::text($b['pricing_mode']??$qv['pricing_mode'],20)),'pricing_value'=>(float)($b['pricing_value']??$qv['pricing_value']),'rounding_step'=>(float)($b['rounding_step']??$qv['rounding_step']),
            'included_text'=>(string)($b['included_text']??$qv['included_text']),'excluded_text'=>(string)($b['excluded_text']??$qv['excluded_text']),'terms_text'=>(string)($b['terms_text']??$qv['terms_text'])
        ];
        if($fields['total_guests']<=0) $fields['total_guests']=$fields['adults']+$fields['children']+$fields['infants']+$fields['foc'];
        if($fields['paying_pax']<=0) $fields['paying_pax']=max(1,$fields['adults']+$fields['children']);
        $st=$db->prepare("UPDATE quote_versions SET version_status=?,tour_name=?,start_date=?,end_date=?,adults=?,children=?,infants=?,foc=?,total_guests=?,paying_pax=?,hotel_level=?,tour_type=?,guide_language=?,meals=?,fx_rate=?,pricing_mode=?,pricing_value=?,rounding_step=?,schedule_json=?,proposal_json=?,included_text=?,excluded_text=?,terms_text=? WHERE id=?");
        $st->execute([$status,$fields['tour_name'],$fields['start_date'],$fields['end_date'],$fields['adults'],$fields['children'],$fields['infants'],$fields['foc'],$fields['total_guests'],$fields['paying_pax'],$fields['hotel_level'],$fields['tour_type'],$fields['guide_language'],$fields['meals'],$fields['fx_rate'],$fields['pricing_mode'],$fields['pricing_value'],$fields['rounding_step'],self::json($schedule),self::json($proposal),$fields['included_text'],$fields['excluded_text'],$fields['terms_text'],$qv['id']]);
        $db->prepare('UPDATE quote_versions SET document_language=?,approved_by=NULL,approved_at=NULL WHERE id=?')->execute([$language,$qv['id']]);
        $db->prepare('DELETE FROM quote_bundle_approvals WHERE quote_version_id=?')->execute([$qv['id']]);
        $contextChanged=false;foreach(['start_date','end_date','adults','children','infants','paying_pax','total_guests','foc'] as $key)if((string)$fields[$key]!== (string)$qv[$key])$contextChanged=true;
        if($contextChanged){$db->prepare('UPDATE quote_cost_items SET review_required=1 WHERE quote_version_id=?')->execute([$qv['id']]);$options=self::all($db,'SELECT id,snapshot_json FROM quote_options WHERE quote_version_id=?',[$qv['id']]);foreach($options as $option){$snap=json_decode($option['snapshot_json'],true);$snap['review_required']=true;$db->prepare('UPDATE quote_options SET snapshot_json=? WHERE id=?')->execute([self::json($snap),$option['id']]);}}
        $p=self::quotePrice($db,(int)$qv['id'],$b);
        $db->prepare('UPDATE quote_versions SET total_cost=?,cost_per_paying_pax=?,selling_per_pax=?,total_selling=?,profit_amount=?,margin_pct=?,markup_pct=?,pricing_mode=?,pricing_value=?,rounding_step=?,fx_rate=? WHERE id=?')
            ->execute([$p['total_cost'],$p['cost_per_paying_pax'],$p['selling_per_pax'],$p['total_selling'],$p['profit_amount'],$p['margin_pct'],$p['markup_pct'],$p['pricing_mode'],$p['pricing_value'],$p['rounding_step'],$p['fx_rate'],$qv['id']]);
        return self::one($db,'SELECT * FROM quote_versions WHERE id=?',[$qv['id']])?:[];
    }

