    public static function reportSummary(PDO $db,array $user,mixed $month): array {
        self::requirePerm($db,$user,'report.view');
        if(!is_string($month)||!preg_match('/^[0-9]{4}-(0[1-9]|1[0-2])$/',$month))throw new InvalidArgumentException('Month must be YYYY-MM');
        $start=DateTimeImmutable::createFromFormat('!Y-m-d',$month.'-01');
        if(!$start||$start->format('Y-m')!==$month)throw new InvalidArgumentException('Invalid month');
        $from=$start->format('Y-m-d');$until=$start->modify('+1 month')->format('Y-m-d');$cid=(int)$user['company_id'];
        $sales=self::one($db,"SELECT COUNT(*) inquiries,COALESCE(SUM(CASE WHEN status='CONFIRMED' THEN 1 ELSE 0 END),0) confirmed,COALESCE(SUM(CASE WHEN status='LOST' THEN 1 ELSE 0 END),0) lost FROM inquiries WHERE company_id=? AND created_at>=? AND created_at<?",[$cid,$from.' 00:00:00',$until.' 00:00:00']);
        foreach($sales as &$count)$count=(int)$count;unset($count);
        $cohort="company_id=? AND operations_status<>'CANCELLED' AND start_date>=? AND start_date<?";$args=[$cid,$from,$until];
        $book=self::one($db,"SELECT COUNT(*) bookings,COALESCE(SUM(CASE WHEN risk_level IN ('HIGH','CRITICAL') THEN 1 ELSE 0 END),0) at_risk FROM bookings WHERE $cohort",$args);
        foreach($book as &$count)$count=(int)$count;unset($count);
        $revenue=self::all($db,"SELECT selling_currency currency,COALESCE(SUM(confirmed_selling),0) amount,COUNT(*) bookings FROM bookings WHERE $cohort GROUP BY selling_currency ORDER BY selling_currency",$args);
        foreach($revenue as &$group){$group['amount']=round((float)$group['amount'],2);$group['bookings']=(int)$group['bookings'];}unset($group);
        $profits=null;$review=[];
        if(self::can($db,$user,'profit.view')){
            $profits=[];
            foreach(self::all($db,"SELECT id,booking_ref,selling_currency FROM bookings WHERE $cohort ORDER BY id",$args) as $booking){
                $currency=$booking['selling_currency'];
                $profits[$currency]??=['currency'=>$currency,'expected_profit'=>0,'forecast_profit'=>0,'actual_profit'=>0,'actual_final_count'=>0,'pending_actual_count'=>0,'review_required_count'=>0];
                $group=&$profits[$currency];
                try{
                    $p=FinanceLedger::profit($db,$cid,(int)$booking['id']);
                    if($p['currency']!==$currency)throw new DomainException('Ledger currency differs from booking selling currency');
                    $group['expected_profit']+=(int)round($p['expected_profit']*100);$group['forecast_profit']+=(int)round($p['forecast_profit']*100);
                    if($p['actual_final']&&$p['actual_profit']!==null){$group['actual_profit']+=(int)round($p['actual_profit']*100);$group['actual_final_count']++;}
                    else $group['pending_actual_count']++;
                }catch(DomainException $e){
                    $group['review_required_count']++;$group['pending_actual_count']++;
                    $review[]=['booking_id'=>(int)$booking['id'],'booking_ref'=>$booking['booking_ref'],'currency'=>$currency,'reason'=>$e->getMessage()];
                }
                unset($group);
            }
            ksort($profits);
            foreach($profits as &$group){
                $group['expected_profit']=$group['review_required_count']?null:$group['expected_profit']/100;
                $group['forecast_profit']=$group['review_required_count']?null:$group['forecast_profit']/100;
                $group['actual_profit']=$group['actual_final_count']?$group['actual_profit']/100:null;
            }unset($group);$profits=array_values($profits);
        }
        return ['ok'=>true,'month'=>$month,'timezone'=>date_default_timezone_get(),'date_range'=>['start'=>$from,'end_exclusive'=>$until],
            'definitions'=>['sales'=>'Inquiries created within the calendar month; confirmed/lost are their current states.','bookings'=>'Non-cancelled bookings departing within the calendar month.','revenue'=>'Confirmed selling grouped by original selling currency; no conversion or cross-currency total.','profit'=>'Modern ledger values for the departure cohort. Actual profit includes finalized bookings only; pending/review counts remain explicit.'],
            'sales'=>$sales,'bookings'=>$book,'revenue_by_currency'=>$revenue,'profit_by_currency'=>$profits,'profit_review_required'=>$review];
    }

    public static function handle(string $route,string $method,PDO $db,array $config,array $user): bool {
        $companyId=(int)$user['company_id']; $userId=(int)$user['id'];
        if(!self::tableExists($db,'trips')) return false;

        // Complete dashboard and global search
        if($route==='dashboard' && $method==='GET'){
            self::requirePerm($db,$user,'task.view');
            $stats=[];
            $stats['inquiries_open']=(int)(self::one($db,"SELECT COUNT(*) c FROM inquiries WHERE company_id=? AND status NOT IN ('CONFIRMED','LOST','CANCELLED')",[$companyId])['c']??0);
            $stats['quotes_sent']=(int)(self::one($db,"SELECT COUNT(*) c FROM quotes WHERE company_id=? AND status IN ('SENT','FOLLOW_UP')",[$companyId])['c']??0);
            $stats['bookings_active']=(int)(self::one($db,"SELECT COUNT(*) c FROM bookings WHERE company_id=? AND operations_status NOT IN ('COMPLETED','CANCELLED')",[$companyId])['c']??0);
            $stats['bookings_risk']=(int)(self::one($db,"SELECT COUNT(*) c FROM bookings WHERE company_id=? AND risk_level IN ('HIGH','CRITICAL') AND operations_status NOT IN ('COMPLETED','CANCELLED')",[$companyId])['c']??0);
            $stats['ar_outstanding']=self::can($db,$user,'customer_ar.view')?(float)(self::one($db,"SELECT COALESCE(SUM(GREATEST(0,confirmed_selling-(SELECT COALESCE(SUM(cp.amount),0) FROM customer_payments cp WHERE cp.booking_id=b.id AND cp.currency=b.selling_currency)-(SELECT COALESCE(SUM(pa.amount),0) FROM payment_allocations pa JOIN customer_invoices i ON i.id=pa.invoice_id WHERE i.booking_id=b.id AND i.currency=b.selling_currency))),0) a FROM bookings b WHERE company_id=? AND selling_currency='USD' AND operations_status<>'CANCELLED'",[$companyId])['a']??0):null;
            $stats['ap_outstanding']=self::can($db,$user,'supplier_ap.view')?(float)(self::one($db,"SELECT COALESCE(SUM(p.balance*CASE WHEN p.currency='USD' THEN v.fx_rate ELSE 1 END),0) a FROM supplier_payables p JOIN bookings b ON b.id=p.booking_id JOIN quote_versions v ON v.quote_id=b.quote_id AND v.version_no=b.confirmed_quote_version_no WHERE p.company_id=? AND p.currency IN ('USD','VND') AND p.status IN ('UNPAID','PART_PAID')",[$companyId])['a']??0):null;
            $stats['rates_expiring']=(int)(self::one($db,"SELECT COUNT(*) c FROM rate_versions rv JOIN rates r ON r.id=rv.rate_id WHERE r.company_id=? AND rv.approval_status='APPROVED' AND rv.valid_to BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)",[$companyId])['c']??0);
            $tasks=self::all($db,"SELECT t.*,u.full_name owner_name,CASE WHEN t.due_at<NOW() THEN 'OVERDUE' WHEN DATE(t.due_at)=CURDATE() THEN 'DUE_TODAY' WHEN t.due_at<=DATE_ADD(NOW(),INTERVAL 7 DAY) THEN 'UPCOMING' ELSE 'LATER' END due_state FROM tasks t JOIN users u ON u.id=t.owner_user_id WHERE t.company_id=? AND t.status IN ('OPEN','SNOOZED') ORDER BY FIELD(t.priority,'CRITICAL','HIGH','NORMAL'),COALESCE(t.due_at,'2999-12-31') LIMIT 25",[$companyId]);
            $departures=self::all($db,"SELECT id,booking_ref,lead_guest_name,start_date,total_guests,readiness_pct,risk_level,operations_status FROM bookings WHERE company_id=? AND start_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY) AND operations_status<>'CANCELLED' ORDER BY start_date LIMIT 12",[$companyId]);
            Http::json(['ok'=>true,'stats'=>$stats,'tasks'=>$tasks,'departures'=>$departures]);
        }
        if($route==='search' && $method==='GET'){
            $q=self::text($_GET['q']??'',120); if(strlen($q)<2)Http::json(['ok'=>true,'groups'=>[]]); $like='%'.$q.'%'; $g=[];
            if(self::can($db,$user,'booking.view'))$g['bookings']=self::all($db,"SELECT id,booking_ref,lead_guest_name,start_date,operations_status FROM bookings WHERE company_id=? AND (booking_ref LIKE ? OR lead_guest_name LIKE ? OR lead_whatsapp LIKE ?) ORDER BY updated_at DESC LIMIT 6",[$companyId,$like,$like,$like]);
            if(self::can($db,$user,'sales.view'))$g['quotes']=self::all($db,"SELECT q.id,q.quote_ref,q.status,t.title FROM quotes q JOIN trips t ON t.id=q.trip_id WHERE q.company_id=? AND (q.quote_ref LIKE ? OR t.title LIKE ? OR t.lead_contact_name LIKE ?) ORDER BY q.updated_at DESC LIMIT 6",[$companyId,$like,$like,$like]);
            if(self::can($db,$user,'supplier.view'))$g['suppliers']=self::all($db,"SELECT id,supplier_ref,name,supplier_type,city FROM suppliers WHERE company_id=? AND status<>'ARCHIVED' AND (name LIKE ? OR supplier_ref LIKE ?) ORDER BY preferred DESC,name LIMIT 6",[$companyId,$like,$like]);
            if(self::can($db,$user,'booking.view'))$g['flights']=self::all($db,"SELECT f.id,f.flight_number,f.flight_date,b.id booking_id,b.booking_ref,b.lead_guest_name FROM flights f JOIN bookings b ON b.id=f.booking_id WHERE b.company_id=? AND f.flight_number LIKE ? ORDER BY f.flight_date DESC LIMIT 6",[$companyId,$like]);
            if(self::can($db,$user,'customer_ar.view'))$g['finance']=self::all($db,"SELECT i.id,i.invoice_ref,i.total,i.balance,i.status,b.booking_ref FROM customer_invoices i JOIN bookings b ON b.id=i.booking_id WHERE i.company_id=? AND i.invoice_ref LIKE ? ORDER BY i.created_at DESC LIMIT 6",[$companyId,$like]);
            Http::json(['ok'=>true,'groups'=>$g]);
        }

        // Customers / Agents
        if($route==='customers' && $method==='GET'){
            self::requirePerm($db,$user,'sales.view'); $q=self::text($_GET['q']??'',120);$args=[$companyId];$where="company_id=? AND status<>'ARCHIVED'";if($q){$where.=' AND (full_name LIKE ? OR company_name LIKE ? OR whatsapp LIKE ? OR email LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);} Http::json(['ok'=>true,'items'=>self::all($db,"SELECT * FROM customers WHERE $where ORDER BY updated_at DESC LIMIT 200",$args)]);
        }
        if($route==='customers' && $method==='POST'){
            // Validate owner before generating a reference or inserting the customer.
            self::requirePerm($db,$user,'customer.manage');$b=self::body();
