            self::requirePerm($db,$user,'operations.view');$o=self::order($db,$companyId,(int)$m[1]);$supplier=self::one($db,'SELECT * FROM suppliers WHERE company_id=? AND id=?',[$companyId,$o['supplier_id']]);$bkg=self::booking($db,$companyId,(int)$o['booking_id']);$services=self::all($db,"SELECT bs.*,sos.service_status FROM supplier_order_services sos JOIN booking_services bs ON bs.id=sos.service_id WHERE sos.order_id=? ORDER BY bs.service_date,bs.start_time,bs.id",[$o['id']]);$revisions=self::all($db,'SELECT * FROM supplier_order_revisions WHERE order_id=? ORDER BY revision_no DESC',[$o['id']]);$confirmations=self::all($db,'SELECT * FROM supplier_confirmations WHERE order_id=? ORDER BY confirmed_at DESC',[$o['id']]);Http::json(['ok'=>true,'order'=>$o,'supplier'=>$supplier,'booking'=>$bkg,'services'=>$services,'revisions'=>$revisions,'confirmations'=>$confirmations]);
        }

        // Finance control lists
        if($route==='finance/ar' && $method==='GET'){
            self::requirePerm($db,$user,'customer_ar.view');$sql="SELECT b.id,b.booking_ref,b.lead_guest_name,b.start_date,b.confirmed_selling total,b.selling_currency currency,COALESCE((SELECT SUM(cp.amount) FROM customer_payments cp WHERE cp.booking_id=b.id),0) paid,GREATEST(0,b.confirmed_selling-COALESCE((SELECT SUM(cp2.amount) FROM customer_payments cp2 WHERE cp2.booking_id=b.id),0)) balance,(SELECT MIN(ci.due_date) FROM customer_invoices ci WHERE ci.booking_id=b.id AND ci.status NOT IN ('PAID','CANCELLED') AND ci.balance>0) next_due,b.customer_payment_status status FROM bookings b WHERE b.company_id=? AND b.operations_status<>'CANCELLED' ORDER BY (balance>0) DESC,COALESCE(next_due,'2999-12-31') LIMIT 500";Http::json(['ok'=>true,'items'=>self::all($db,$sql,[$companyId])]);
        }
        if($route==='finance/ap' && $method==='GET'){
            self::requirePerm($db,$user,'supplier_ap.view');$sql="SELECT sp.*,s.name supplier_name,b.booking_ref,b.lead_guest_name FROM supplier_payables sp JOIN suppliers s ON s.id=sp.supplier_id JOIN bookings b ON b.id=sp.booking_id WHERE sp.company_id=? AND sp.status<>'CANCELLED' ORDER BY FIELD(sp.status,'UNPAID','PART_PAID','PAID'),COALESCE(sp.due_date,'2999-12-31') LIMIT 500";Http::json(['ok'=>true,'items'=>self::all($db,$sql,[$companyId])]);
        }
        if($route==='finance/profitability' && $method==='GET'){
            self::requirePerm($db,$user,'profit.view');$rows=self::all($db,"SELECT id,booking_ref,lead_guest_name,start_date,confirmed_selling,selling_currency,operations_status FROM bookings WHERE company_id=? AND operations_status<>'CANCELLED' ORDER BY start_date DESC LIMIT 300",[$companyId]);$items=[];foreach($rows as $r){$sum=self::financeSummary($db,(int)$r['id']);$items[]=array_merge($r,['expected_profit'=>$sum['expected_profit'],'forecast_profit'=>$sum['forecast_profit'],'actual_profit'=>$sum['actual_profit'],'actual_complete'=>$sum['actual_complete']]);}Http::json(['ok'=>true,'items'=>$items]);
        }

        // Company settings
        if($route==='settings' && $method==='GET'){
            self::requirePerm($db,$user,'settings.manage');$rows=self::all($db,'SELECT setting_key,setting_value FROM company_settings WHERE company_id=?',[$companyId]);$out=[];foreach($rows as $x)$out[$x['setting_key']]=$x['setting_value'];Http::json(['ok'=>true,'settings'=>$out]);
        }
        if($route==='settings' && $method==='PUT'){
            self::requirePerm($db,$user,'settings.manage');$b=self::body();$allowed=['default_fx','default_margin','minimum_margin','quote_followup_days','supplier_followup_hours','rate_expiry_days','departure_warning_days','company_bank_details','invoice_terms'];$st=$db->prepare('INSERT INTO company_settings(company_id,setting_key,setting_value,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');foreach($allowed as $k)if(array_key_exists($k,$b))$st->execute([$companyId,$k,(string)$b[$k],$userId]);Audit::log($db,$companyId,$userId,'SETTINGS_UPDATED','company',$companyId,null,array_intersect_key($b,array_flip($allowed)));Http::json(['ok'=>true]);
        }

        // Reports
        if($route==='reports/summary' && $method==='GET'){
            Http::json(self::reportSummary($db,$user,$_GET['month']??date('Y-m')));
        }

        return false;
    }
}
